import React, { useState, useEffect, useRef } from 'react';
import './ProfilArtiste.css';
import { Share2, UserPlus, UserCheck } from 'lucide-react';
import Partager from './Partager';

function ProfilArtiste({ allerVers, utilisateur, artisteId }) {
  const [artiste, setArtiste] = useState(null);
  const [musiques, setMusiques] = useState([]);
  const [nbAbonnes, setNbAbonnes] = useState(0);
  const [estAbonne, setEstAbonne] = useState(false);
  const [chargement, setChargement] = useState(true);
  const [lecteurActif, setLecteurActif] = useState(null);
  const [filtreType, setFiltreType] = useState('tous');
  const audioRef = useRef(null);
  const [partagerOuvert, setPartagerOuvert] = useState(false);

  useEffect(() => {
    fetch(`/api/profil/${artisteId}`)
      .then(res => res.json())
      .then(data => {
        setArtiste(data.artiste);
        setMusiques(data.musiques);
        setNbAbonnes(data.nb_abonnes);
        setChargement(false);
      })
      .catch(() => setChargement(false));

    if (utilisateur) {
      fetch(`/api/profil/${artisteId}/abonnements?abonne_id=${utilisateur.id}`)
        .then(res => res.json())
        .then(data => setEstAbonne(data.estAbonne));
    }
  }, [artisteId, utilisateur]);

  const handleAbonnement = async () => {
    if (!utilisateur) { allerVers('login'); return; }

    const route = estAbonne ? '/api/profil/desabonner' : '/api/profil/abonner';
    await fetch(route, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ abonne_id: utilisateur.id, artiste_id: parseInt(artisteId) })
    });

    setEstAbonne(!estAbonne);
    setNbAbonnes(prev => estAbonne ? prev - 1 : parseInt(prev) + 1);
  };

  const jouerExtrait = (musique) => {
    if (lecteurActif === musique.id) {
      audioRef.current.pause();
      setLecteurActif(null);
    } else {
      if (audioRef.current) audioRef.current.pause();
      audioRef.current = new Audio(musique.fichier_url);
      audioRef.current.play();
      setLecteurActif(musique.id);
      setTimeout(() => {
        if (audioRef.current) audioRef.current.pause();
        setLecteurActif(null);
      }, 20000);
    }
  };

  const musiquesFiltrees = filtreType === 'tous'
  ? (musiques || [])
  : (musiques || []).filter(m => m.type === filtreType);

  if (chargement) return (
    <div className="profil-page">
      <div className="chargement">Chargement du profil...</div>
    </div>
  );

  return (
    <div className="profil-page">
      <header className="header">
        <div className="logo" onClick={() => allerVers('accueil')}>🎵 Varim Music</div>
        <nav className="nav">
          <a href="#" onClick={() => allerVers('accueil')}>Accueil</a>
          <a href="#" onClick={() => allerVers('catalogue')}>Catalogue</a>
        </nav>
        <div className="auth-buttons">
          {utilisateur ? (
            <>
              <span className="user-prenom">👋 {utilisateur.prenom}</span>
              {utilisateur.role === 'artiste' && utilisateur.id === parseInt(artisteId) && (
                <button className="btn-dashboard" onClick={() => allerVers('mon-compte')}>
                  ⚙️ Mon Compte
                </button>
              )}
              <button className="btn-login" onClick={() => {
                localStorage.removeItem('token');
                localStorage.removeItem('utilisateur');
                allerVers('accueil');
              }}>Déconnexion</button>
            </>
          ) : (
            <>
              <button className="btn-login" onClick={() => allerVers('login')}>Connexion</button>
              <button className="btn-register" onClick={() => allerVers('register')}>S'inscrire</button>
            </>
          )}
        </div>
      </header>

      <div className="profil-hero">
        <div className="profil-avatar">
          {artiste?.photo_profil ? (
            <img src={artiste.photo_profil} alt={artiste.prenom} />
          ) : (
            <div className="avatar-defaut">🎤</div>
          )}
        </div>
        <div className="profil-meta">
          <h1 className="profil-nom">
            {artiste?.nom_artiste || artiste?.prenom}
          </h1>
          {artiste?.bio && <p className="profil-bio">{artiste.bio}</p>}
          <div className="profil-stats">
            <div className="profil-stat">
              <span className="stat-val">{musiques.length}</span>
              <span className="stat-lab">Musiques</span>
            </div>
            <div className="profil-stat">
              <span className="stat-val">{nbAbonnes}</span>
              <span className="stat-lab">Abonnés</span>
            </div>
          </div>
          <div className="profil-actions">
            {utilisateur && utilisateur.id !== parseInt(artisteId) && (
              <button className={`btn-abonnement ${estAbonne ? 'abonne' : ''}`} onClick={handleAbonnement}>
                {estAbonne ? <><UserCheck size={16} /> Abonné</> : <><UserPlus size={16} /> S'abonner</>}
              </button>
            )}
            <button className="btn-partager" onClick={() => setPartagerOuvert(true)}>
              <Share2 size={16} /> Partager
            </button>
          </div>
        </div>
      </div>
      {partagerOuvert && (
  <Partager
    lien={`${window.location.origin}?profil=${artisteId}`}
    titre={`${artiste?.nom_artiste || artiste?.prenom} sur Varim Music`}
    onFermer={() => setPartagerOuvert(false)}
  />
)}
      <div className="profil-contenu">
        <div className="profil-filtres">
          <button
            className={`filtre-btn ${filtreType === 'tous' ? 'actif' : ''}`}
            onClick={() => setFiltreType('tous')}
          >Tous</button>
          <button
            className={`filtre-btn ${filtreType === 'single' ? 'actif' : ''}`}
            onClick={() => setFiltreType('single')}
          >🎵 Singles</button>
          <button
            className={`filtre-btn ${filtreType === 'album' ? 'actif' : ''}`}
            onClick={() => setFiltreType('album')}
          >💿 Albums</button>
        </div>

        {musiquesFiltrees.length === 0 ? (
          <div className="vide">Aucune musique publiée.</div>
        ) : (
          <div className="grille-musiques">
            {musiquesFiltrees.map(musique => (
              <div key={musique.id} className="carte-musique">
                <div className="carte-pochette">
                  {musique.pochette_url ? (
                    <img src={musique.pochette_url} alt={musique.titre} />
                  ) : (
                    <div className="pochette-defaut">🎵</div>
                  )}
                  <div className="carte-type">{musique.type}</div>
                </div>
                <div className="carte-infos">
                  <h3 className="carte-titre">{musique.titre}</h3>
                  <p className="carte-genre">🎸 {musique.genre}</p>
                  <p className="carte-prix">{musique.prix} FCFA</p>
                </div>
                <div className="carte-actions">
                  {musique.type === 'album' ? (
                    <button className="btn-extrait" onClick={() => allerVers('album_' + musique.id)}>
                      👁 Voir l'album
                    </button>
                  ) : (
                    <button
                      className={`btn-extrait ${lecteurActif === musique.id ? 'en-lecture' : ''}`}
                      onClick={() => jouerExtrait(musique)}
                    >
                      {lecteurActif === musique.id ? '⏸ Stop' : '▶ Extrait 20s'}
                    </button>
                  )}
                  <button className="btn-acheter" onClick={() => allerVers('achat_' + musique.id)}>
                    🛒 Acheter
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default ProfilArtiste;
